window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bb74efddda081958"]={"versions": [{"id": "FIG-bb74efddda081958", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur internen algorithmischen Ablauflogik von AUTOSAR E2E Profile 4. Das Diagramm spezifiziert den Teilablauf „Compute offset“ innerhalb des E2E-Protokolls (AUTOSAR PRS E2EProtocol).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aufrufende Funktionen (Kontextsymbole): <code>E2E_P04Protect()</code>, <code>E2E_P04Check()</code> (jeweils als aufrufende Aktivitäten mit Referenzsymbol dargestellt)\n</li><li>Eingangsdaten / Konfigurationsstruktur: <code>Config-&gt;Offset</code> (Offset-Angabe in Bit)\n</li><li>Lokale Variable: <code>Offset</code> vom Datentyp <code>uint16</code> (Offset-Angabe in Byte)\n</li><li>Strukturelemente: Initialer Knoten (Start), Aktion <code>Offset = Config-&gt;Offset / 8</code>, Aktivitätsendknoten (Stop), Kommentar-/Notiz-Element mit gestrichelter Assoziationslinie.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den initialen Knoten.\n</li><li>Ausführung der Aktion <code>Offset = Config-&gt;Offset / 8</code>: Der in Bits konfigurierte Offset-Wert <code>Config-&gt;Offset</code> wird durch 8 dividiert, um den Byte-Offset zu ermitteln, und in der lokalen Variablen <code>Offset</code> abgelegt.\n</li><li>Übergang in den Aktivitätsendknoten zur Beendigung des Berechnungsschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Berechnungsvorschrift für E2E Profile 4. Die Bit-zu-Byte-Umrechnung des E2E-Offsets muss exakt mittels Ganzzahldivision durch 8 in eine vorzeichenlose 16-Bit-Ganzzahl (<code>uint16</code>) erfolgen. Dieser Berechnungsschritt ist identisch sowohl für den Schutz (<code>E2E_P04Protect()</code>) als auch für die Prüfung (<code>E2E_P04Check()</code>) von Nachrichten anzuwenden.</p>"}, {"id": "FIG-fb731f356c72658f", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur internen algorithmischen Ablauflogik von AUTOSAR E2E Profile 4. Das Diagramm spezifiziert den Teilablauf „Compute offset“ innerhalb des E2E-Protokolls (AUTOSAR PRS E2EProtocol).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aufrufende Funktionen (Kontextsymbole): <code>E2E_P04Protect()</code>, <code>E2E_P04Check()</code>, <code>E2E_P04Forward()</code> (jeweils als Aktivitäten mit Referenzsymbol dargestellt)\n</li><li>Eingangsdaten / Konfigurationsstruktur: <code>Config-&gt;Offset</code> (Offset-Angabe in Bit)\n</li><li>Lokale Variable: <code>Offset</code> vom Datentyp <code>uint16</code> (Offset-Angabe in Byte)\n</li><li>Strukturelemente: Initialer Knoten (Start), Aktion <code>Offset = Config-&gt;Offset / 8</code>, Aktivitätsendknoten (Stop), Notiz-Element mit gestrichelter Assoziationslinie.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den initialen Knoten.\n</li><li>Ausführung der Aktion <code>Offset = Config-&gt;Offset / 8</code>: Der in Bits konfigurierte Offset-Wert <code>Config-&gt;Offset</code> wird durch 8 dividiert, um den Byte-Offset zu ermitteln, und in der lokalen Variablen <code>Offset</code> abgelegt.\n</li><li>Übergang in den Aktivitätsendknoten zur Beendigung des Berechnungsschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Berechnungsvorschrift für E2E Profile 4. Die Bit-zu-Byte-Umrechnung des E2E-Offsets erfolgt mittels Division durch 8 in eine lokale <code>uint16</code>-Variable. Dieser Berechnungsschritt ist verbindlich für die Schutzfunktion (<code>E2E_P04Protect()</code>), die Prüffunktion (<code>E2E_P04Check()</code>) sowie die Weiterleitungsfunktion (<code>E2E_P04Forward()</code>) anzuwenden.</p>"}, {"id": "FIG-d1e340ea1e25e5a9", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur internen algorithmischen Ablauflogik von AUTOSAR E2E Profile 4. Das Diagramm spezifiziert den Teilablauf „Compute offset“ innerhalb des E2E-Protokolls (AUTOSAR PRS E2EProtocol).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aufrufende Funktionen (Kontextsymbole): <code>E2E_P04Protect()</code>, <code>E2E_P04Check()</code>, <code>E2E_P04Forward()</code> (jeweils als Aktivitäten mit Referenzsymbol dargestellt)\n</li><li>Eingangsdaten / Konfigurationsstruktur: <code>Config-&gt;Offset</code> (Offset-Angabe in Bit)\n</li><li>Lokale Variable: <code>Offset</code> vom Datentyp <code>uint16</code> (Offset-Angabe in Byte)\n</li><li>Strukturelemente: Initialer Knoten (Start), Aktion <code>Offset = Config-&gt;Offset / 8</code>, Aktivitätsendknoten (Stop), Notiz-Element mit gestrichelter Assoziationslinie.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den initialen Knoten.\n</li><li>Ausführung der Aktion <code>Offset = Config-&gt;Offset / 8</code>: Der in Bits konfigurierte Offset-Wert <code>Config-&gt;Offset</code> wird durch 8 dividiert, um den Byte-Offset zu ermitteln, und in der lokalen Variablen <code>Offset</code> abgelegt.\n</li><li>Übergang in den Aktivitätsendknoten zur Beendigung des Berechnungsschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Berechnungsvorschrift für E2E Profile 4. Die Bit-zu-Byte-Umrechnung des E2E-Offsets erfolgt mittels Division durch 8 in eine lokale <code>uint16</code>-Variable. Dieser Berechnungsschritt ist verbindlich für die Schutzfunktion (<code>E2E_P04Protect()</code>), die Prüffunktion (<code>E2E_P04Check()</code>) sowie die Weiterleitungsfunktion (<code>E2E_P04Forward()</code>) anzuwenden.</p>"}], "trans": [{"from": "FIG-bb74efddda081958", "to": "FIG-fb731f356c72658f", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Kontext/Aufrufer: Das Aktivitätssymbol <code>E2E_P04Forward()</code> wird links neben dem Ablauf ergänzt, sodass der Schritt ”Compute offset” auch für die Weiterleitungsfunktion von Profile 4 gilt.\n</li></ul>"}, {"from": "FIG-fb731f356c72658f", "to": "FIG-d1e340ea1e25e5a9", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
